            .field("url", &"[REDACTED]")
            .field("header_names", &self.headers.keys().collect::<Vec<_>>())
            .finish()
    }
}

/// HTTP implementation of the private admission port. It is scoped to one
/// run-owned Boss bridge and shares that bridge's bearer authentication.
