fn digest_json(value: &Value) -> String {
    let digest = Sha256::digest(value.to_string().as_bytes());
    let encoded = digest
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    format!("sha256:{encoded}")
}

const fn source_identity(source: ToolSource) -> &'static str {
    match source {
        ToolSource::NativeSkill => "native_skill",
        ToolSource::Mcp => "mcp",
        ToolSource::BuiltIn => "builtin",
    }
}

const fn effect_identity(effect: ToolEffect) -> &'static str {
    match effect {
        ToolEffect::ReadOnly => "read_only",
        ToolEffect::ExternalMutation => "external_mutation",
        ToolEffect::CodeExecution => "code_execution",
        ToolEffect::Unknown => "unknown",
    }
}

const fn approval_identity(approval: ApprovalClass) -> &'static str {
    match approval {
        ApprovalClass::NotRequired => "not_required",
        ApprovalClass::Required => "required",
    }
}

mod approval_class_wire {
    use serde::{Deserialize, Deserializer, Serializer};

    use crate::uar::tools::descriptor::ApprovalClass;

    pub fn serialize<S>(value: &ApprovalClass, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        serializer.serialize_str(match value {
            ApprovalClass::NotRequired => "not_required",
            ApprovalClass::Required => "required",
        })
    }

    pub fn deserialize<'de, D>(deserializer: D) -> Result<ApprovalClass, D::Error>
    where
        D: Deserializer<'de>,
    {
        match String::deserialize(deserializer)?.as_str() {
            "not_required" => Ok(ApprovalClass::NotRequired),
            "required" => Ok(ApprovalClass::Required),
            value => Err(serde::de::Error::unknown_variant(
                value,
                &["not_required", "required"],
            )),
        }
    }
}

